insert into public.lessons(unit_id,slug,title,description,lesson_type,estimated_minutes,sequence,learning_objectives,content,points_reward,is_published)
select u.id,'contar-lo-que-hiciste','Tell someone what you did','Use regular preterite forms and sequencing expressions to describe a completed experience.','core',30,1,
'["Recognize common time expressions for completed events","Use regular -ar, -er, and -ir preterite endings","Connect actions with primero, después, luego, and al final","Write a short personal narrative"]'::jsonb,
'{"sections":[{"body":"In this lesson, you will learn to narrate completed actions in a clear sequence. The goal is not to memorize a chart in isolation. It is to understand how Spanish marks completed events and then use those patterns to tell a real story.","type":"intro","title":"Tell someone what you did","eyebrow":"01 · LEARNING OBJECTIVE"},{"note":"Learn the phrase as a complete unit. For example, remember quedar con alguien—not only quedar. These chunks make it easier to speak without translating word by word.","type":"vocabulary","items":[{"term":"ayer","example":"Ayer trabajé hasta tarde.","meaning":"yesterday"},{"term":"anteayer","example":"Anteayer visité a un amigo.","meaning":"the day before yesterday"},{"term":"la semana pasada","example":"La semana pasada viajamos.","meaning":"last week"},{"term":"primero","example":"Primero preparé el desayuno.","meaning":"first"},{"term":"después / luego","example":"Después tomé el autobús.","meaning":"afterward / then"},{"term":"al final","example":"Al final regresé a casa.","meaning":"in the end"},{"term":"quedar con alguien","example":"Quedé con mis amigos en el centro.","meaning":"to meet up with someone"},{"term":"pasarlo bien","example":"Lo pasamos muy bien.","meaning":"to have a good time"}],"title":"Useful words and phrases","eyebrow":"02 · LANGUAGE BEFORE PRACTICE"},{"text":"El sábado pasado tuve un día diferente. Por la mañana, me levanté temprano y preparé café. Después, quedé con una amiga en el centro. Caminamos por varias calles, entramos en una librería y compramos un regalo para su hermano. Al mediodía, almorzamos en un restaurante pequeño. Yo pedí una sopa y ella eligió una ensalada. Más tarde, visitamos un mercado donde encontramos productos de varias regiones de México. Tomé algunas fotos y compré fruta para la semana. Al final de la tarde, tomamos el autobús y regresamos a casa. Estaba cansado, pero lo pasé muy bien porque hice algo diferente y compartí el día con una buena amiga.","type":"reading","title":"Un sábado diferente","eyebrow":"03 · READ FOR MEANING","glossary":[["quedé","I met up"],["eligió","she chose"],["encontramos","we found"],["regresamos","we returned"],["lo pasé muy bien","I had a very good time"]],"instructions":"Read the passage aloud twice. First follow the story. On the second reading, notice the verbs that describe completed events."},{"body":"Use the preterite to present an action as a completed event. It is common with a finished time frame such as ayer, el sábado pasado, anoche, or la semana pasada.","note":"Important: nosotros forms such as hablamos can be present OR preterite. The time expression and context tell you which meaning is intended. Also notice the written accents: habló (he spoke) is different from hablo (I speak).","type":"grammar","steps":["Find the subject: who did the action?","Choose the matching verb ending.","Look for a finished time expression to confirm the time frame."],"table":{"rows":[["yo","hablé","comí","viví"],["tú","hablaste","comiste","viviste"],["él / ella / usted","habló","comió","vivió"],["nosotros","hablamos","comimos","vivimos"],["ellos / ustedes","hablaron","comieron","vivieron"]],"columns":["Subject","-AR · hablar","-ER · comer","-IR · vivir"],"heading":"Regular preterite endings"},"title":"The preterite: completed events","eyebrow":"04 · GRAMMAR IN CONTEXT","pattern":"TIME + SUBJECT + VERB + EXTRA INFORMATION","examples":[["Ayer preparé café.","Yesterday I made coffee."],["El sábado visitamos el mercado.","On Saturday we visited the market."],["Mis amigos compraron entradas.","My friends bought tickets."]],"patternExample":"Ayer + yo + preparé + café para mis amigos."},{"type":"practice","title":"Choose the form that fits","eyebrow":"05 · GUIDED RETRIEVAL","questions":[{"rule":"yo + -ar verb → -é","retry":"Now complete: Anoche yo _____ (hablar) con mi hermano.","answer":"quedé","prompt":"Ayer yo _____ con una amiga en el centro.","options":["quedé","quedó","quedamos"],"explanation":"The subject is yo, so the regular -ar preterite ending is -é. Quedé means “I met up.”","retryAnswer":"hablé"},{"rule":"nosotros + -ar verb → -amos","retry":"Complete: Ayer nosotros _____ (preparar) la cena.","answer":"visitamos","prompt":"El sábado pasado nosotros _____ el mercado.","options":["visitamos","visitaron","visitó"],"explanation":"Nosotros uses -amos for regular -ar verbs. The form is identical to present tense, so el sábado pasado establishes the past.","retryAnswer":"preparamos"},{"rule":"él / ella + regular -ir verb → -ió","retry":"Complete: Mi hermano _____ (vivir) en Lima durante un año.","answer":"eligió","prompt":"Mi amiga _____ una ensalada.","options":["elegí","eligió","elegimos"],"explanation":"Mi amiga is third-person singular (ella). The preterite form is eligió.","retryAnswer":"vivió"},{"rule":"ellos + -ar verb → -aron","retry":"Complete: Mis padres _____ (comprar) fruta.","answer":"llegaron","prompt":"Mis amigos _____ tarde al restaurante.","options":["llegó","llegamos","llegaron"],"explanation":"Mis amigos is plural (ellos), so the -ar ending is -aron.","retryAnswer":"compraron"},{"rule":"Finished time expression + completed event → preterite","retry":"Choose the completed event: Cada día estudio / Anoche estudié.","answer":"Ayer caminé al trabajo.","prompt":"Which sentence clearly describes a completed action yesterday?","options":["Normalmente camino al trabajo.","Ayer caminé al trabajo.","Estoy caminando al trabajo."],"explanation":"Ayer sets a completed past time frame. Caminé is the yo form of the preterite.","retryAnswer":"Anoche estudié"}],"instructions":"Try each question before opening the explanation. If you miss one, read the rule and try a similar sentence again."},{"type":"production","model":"El domingo pasado fui al parque con un amigo. Primero, caminamos por el sendero. Después, compramos café y hablamos un rato. Al final, regresé a casa y preparé la cena. Lo pasé muy bien.","title":"Tell your own short story","eyebrow":"06 · INDEPENDENT PRODUCTION","prompts":["Where did you go or what did you do?","Who were you with?","What happened first, next, and at the end?","How was the experience?"],"checklist":["I used a finished time expression.","My verbs agree with their subjects.","I used at least three connectors: primero, después, luego, al final.","I wrote complete thoughts, not isolated vocabulary."],"instructions":"Write 5–7 sentences about something you did recently. Use at least four preterite verbs and three sequencing expressions."},{"type":"assessment","title":"Can you use the pattern?","eyebrow":"07 · CHECK YOUR LEARNING","questions":[{"rule":"yo + -ar → -é","retry":"Ayer yo _____ (comprar) pan.","answer":"visité","prompt":"La semana pasada yo _____ a mi prima.","options":["visité","visitó","visitamos"],"explanation":"Yo takes -é in the regular -ar preterite.","retryAnswer":"compré"},{"rule":"ellos + -ar → -aron","retry":"Mis compañeros _____ (estudiar) juntos.","answer":"miraron","prompt":"Anoche mis amigos _____ una película.","options":["miró","miraron","miramos"],"explanation":"Mis amigos means ellos, so the ending is -aron.","retryAnswer":"estudiaron"},{"rule":"nosotros + -er/-ir → -imos","retry":"Ayer nosotros _____ (vivir) una experiencia nueva.","answer":"comimos","prompt":"El sábado nosotros _____ en casa.","options":["comí","comieron","comimos"],"explanation":"Nosotros uses -imos for regular -er and -ir verbs.","retryAnswer":"vivimos"},{"rule":"él / ella + -er → -ió","retry":"Mi hermana _____ (beber) agua.","answer":"comió","prompt":"Which form means “she ate”?","options":["comí","comió","comieron"],"explanation":"Ella takes -ió in the regular -er preterite. The accent is important.","retryAnswer":"bebió"},{"rule":"al final = in the end","retry":"Choose the best ending: _____ regresé a casa.","answer":"al final","prompt":"Which phrase means “in the end”?","options":["primero","después","al final"],"explanation":"Al final means “in the end” and is useful for closing a sequence of events.","retryAnswer":"Al final"}],"instructions":"Complete the short assessment. You need at least 4 out of 5 to pass this lesson. If you miss a question, Nahtive will explain the grammar and give you a retry prompt."}],"objective":"Tell a short story about a completed experience, using regular preterite forms and clear time markers.","estimatedMinutes":30}'::jsonb,30,true
from public.course_units u where u.course_id='71dc9833-bd13-4262-b7be-be1889b81c3f' and u.sequence=1
on conflict(unit_id,slug) do update set title=excluded.title,description=excluded.description,content=excluded.content,learning_objectives=excluded.learning_objectives,is_published=true;
update public.courses set is_published=true where id='71dc9833-bd13-4262-b7be-be1889b81c3f';
